import 'package:flutter/material.dart'; import '../models/models.dart'; import '../services/chatbot_api.dart'; import '../widgets/message_bubble.dart';
class ChatScreen extends StatefulWidget { const ChatScreen({super.key,required this.organization}); final Organization organization; @override State<ChatScreen> createState()=>_ChatScreenState(); }
class _ChatScreenState extends State<ChatScreen>{ final api=ChatbotApi(), input=TextEditingController(); final messages=<ChatMessage>[]; bool sending=false; late final String sessionId; @override void initState(){super.initState();sessionId='parent_demo_001';WidgetsBinding.instance.addPostFrameCallback((_)=>send('Hello',showUser:false));} Future<void> send(String text,{bool showUser=true}) async {if(text.trim().isEmpty||sending)return;setState((){sending=true;if(showUser)messages.add(ChatMessage(text:text,sender:'USER',at:DateTime.now()));});input.clear();try{final r=await api.chat(widget.organization.id,sessionId,text);setState(()=>messages.add(ChatMessage(text:r['message'],sender:'BOT',at:DateTime.now(),options:(r['options'] as List).map((v)=>QuickOption.fromJson(v)).toList())));}catch(_){if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Could not reach the local chatbot service.')));}finally{if(mounted)setState(()=>sending=false);}} @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Row(children:[CircleAvatar(child:Text(widget.organization.name[0])),const SizedBox(width:10),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Row(children:[Flexible(child:Text(widget.organization.name,style:const TextStyle(fontSize:16))),if(widget.organization.verified)const Icon(Icons.verified,color:Color(0xff25D366),size:17)]),const Text('online',style:TextStyle(fontSize:11,color:Colors.white70))]))])),body:Column(children:[Expanded(child:ListView.builder(padding:const EdgeInsets.only(top:10),itemCount:messages.length,itemBuilder:(_,i)=>MessageBubble(message:messages[i],onOption:(o)=>send(o.label)))),if(sending)const Padding(padding:EdgeInsets.all(6),child:Row(children:[SizedBox(width:16,height:16,child:CircularProgressIndicator(strokeWidth:2)),SizedBox(width:8),Text('Typing…')])),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(8),child:Row(children:[Expanded(child:TextField(controller:input,onSubmitted:(v)=>send(v),decoration:const InputDecoration(hintText:'Type a message',filled:true,fillColor:Colors.white,border:OutlineInputBorder(borderRadius:BorderRadius.all(Radius.circular(24)),borderSide:BorderSide.none)))),IconButton(onPressed:()=>send(input.text),icon:const Icon(Icons.send,color:Color(0xff128C7E)))])))]));}
